actions.script:
const dataset=datasetId || 'otel_logs'
ec.service.sync().name('org.moqui.report.ReportServices.get#Dataset').parameters({datasetId:dataset}).call()
const pills=JSON.parse(filtersJson || '[]')
if (!Array.isArray(pills) || pills.length>32) throw new Error('Choose at most 32 filters')
ec.user.setPreference('REPORT_PINNED_'+dataset,JSON.stringify(pills.filter(pill=>pill.pinned)))
let history=[];try{history=JSON.parse(ec.user.getPreference('REPORT_HISTORY_'+dataset) || '[]')}catch(_){}
history=Array.isArray(history)?history:[]
if (String(queryString || '').trim()) ec.user.setPreference('REPORT_HISTORY_'+dataset,JSON.stringify([queryString,...history.filter(query=>query!==queryString)].slice(0,20)))

const options = {datasetId:datasetId || 'otel_logs',from:from || 'now-7d',thru:'now',queryString:queryString || '',filters:JSON.parse(filtersJson || '[]'),pageSize:100,
    sort:cursor ? ['time','__cursor'] : ['-time','-__cursor']}
if (cursor) options.cursor = JSON.parse(cursor)
const result = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters(options).call()
const hits = result.hits || []
let next = cursor ? result.nextCursor : null
if (!cursor && hits.length) {
    const hit = hits[0], timeField = result.dataset.timeField
    next = {datasetId:options.datasetId,sort:[timeField,'__cursor'],values:[hit.body[timeField],hit.documentId+':'+hit.id]}
}
if (!cursor) hits.reverse()
ec.web.sendJsonResponse({hits,nextCursor:next})

if (!/^[a-zA-Z0-9_.:-]{1,80}$/.test(String(panelId || ''))) throw new Error('Choose a panel id using letters, digits, _, ., : or -')
const definition=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId:dashboardId}).call().definition
if (definition.type !== 'dashboard') throw new Error('Choose a dashboard')
definition.body.panels=definition.body.panels || {}
if (definition.body.panels[panelId]) throw new Error('This panel id is already used; choose another id')
definition.body.panels[panelId]={title:panelTitle || 'Explore',visualization:datasetId==='otel_logs'?'logs':'table',queries:[{
    datasetId,mode:'documents',queryString:queryString || '',filters:JSON.parse(filtersJson || '[]'),retrievalMode:retrievalMode || 'lexical',pageSize:1000
}]}
ec.service.sync().name('org.moqui.report.ReportServices.save#Definition').parameters({definition,note:'Added panel from Explore'}).call()

if (savedSearchId) {
    const saved=ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId:savedSearchId}).call().definition
    if (saved.type !== 'search') throw new Error('This definition is not a saved search')
    datasetId=ec.web.parameters.datasetId ?? saved.body.datasetId
    queryString=ec.web.parameters.queryString ?? saved.body.queryString
    from=ec.web.parameters.from ?? saved.body.from;thru=ec.web.parameters.thru ?? saved.body.thru
    retrievalMode=ec.web.parameters.retrievalMode ?? saved.body.retrievalMode
    filtersJson=ec.web.parameters.filtersJson ?? JSON.stringify(saved.body.filters || [])
}
from = from || 'now-7d'; thru = thru || 'now'
savedSearches=ec.service.sync().name('org.moqui.report.ReportServices.list#Definitions').parameters({definitionType:'search'}).call().definitions || []
editableDashboards=(ec.service.sync().name('org.moqui.report.ReportServices.list#Definitions').parameters({definitionType:'dashboard'}).call().definitions || []).filter(definition=>!definition.readOnly && definition.ownerId===ec.user.userId)
datasetList = ec.service.sync().name('org.moqui.report.ReportServices.list#Datasets').call().datasets || []
datasetInfo = ec.service.sync().name('org.moqui.report.ReportServices.get#Dataset').parameters({datasetId:datasetId || 'otel_logs'}).call().dataset
datasetFields = (datasetInfo.fields || []).filter(field=>field.aggregatable)
datasetId = datasetId || 'otel_logs'
if (historyQuery) queryString=historyQuery
const pinKey='REPORT_PINNED_'+datasetId,historyKey='REPORT_HISTORY_'+datasetId
filtersJson=filtersJson || ec.user.getPreference(pinKey) || '[]'
filterPills=JSON.parse(filtersJson)
if (!Array.isArray(filterPills) || filterPills.length>32) throw new Error('Choose at most 32 filters')
if (pillAction==='add') {
    if (filterPills.length>=32) throw new Error('Choose at most 32 filters')
    const field=datasetInfo.fields.find(field=>field.name===pillField && field.searchable!==false)
    if (!field || !['eq','in','exists','prefix','wildcard','range'].includes(pillOperation)) throw new Error('Choose a searchable field and operation')
    const typed=value=>{if(field.type==='number'){const number=Number(value);if(!String(value).trim() || !Number.isFinite(number)) throw new Error('Enter a number');return number}if(field.type==='boolean'){if(!['true','false'].includes(value))throw new Error('Enter true or false');return value==='true'}return value}
    const query={field:{name:pillField,op:pillOperation}}
    if (pillOperation==='in') query.field.values=String(pillValue || '').split(',').map(value=>typed(value.trim()))
    else if (pillOperation==='range') {const values=String(pillValue || '').split(',');if(values.length!==2)throw new Error('Enter lower,upper bounds');if(values[0].trim())query.field.gte=typed(values[0].trim());if(values[1].trim())query.field.lte=typed(values[1].trim())}
    else if (pillOperation!=='exists') query.field.value=typed(pillValue || '')
    filterPills.push({query,label:pillLabel || '',pinned:false,negated:false,disabled:false})
} else if (pillAction) {
    const index=Number(pillIndex),pill=filterPills[index]
    if (!Number.isInteger(index) || !pill) throw new Error('Choose a filter')
    if (pillAction==='remove') filterPills.splice(index,1)
    else {const key={pin:'pinned',negate:'negated',disable:'disabled'}[pillAction];if(!key)throw new Error('Choose a filter action');pill[key]=!pill[key]}
}
filtersJson=JSON.stringify(filterPills)
filterPillRows=filterPills.map((pill,index)=>({index,label:(pill.negated?'NOT ':'')+(pill.label || JSON.stringify(pill.query))+(pill.disabled?' (disabled)':''),pinned:pill.pinned}))
queryHistory=[];try{queryHistory=JSON.parse(ec.user.getPreference(historyKey) || '[]')}catch(_){}
queryHistory=Array.isArray(queryHistory)?queryHistory:[]
queryHistoryOptions=queryHistory.map(value=>({value,text:value}))
const sort = ['-time','-__cursor']
const options = {datasetId,from,thru,queryString:queryString || '',filters:filterPills,sort,retrievalMode:retrievalMode || 'lexical',highlightFields:(datasetInfo.fields || []).filter(field=>field.searchable && field.type==='string').slice(0,20).map(field=>field.name),
    pageIndex:parseInt(pageIndex || '0',10),pageSize:parseInt(pageSize || '50',10)}
if (cursor) options.cursor = JSON.parse(cursor)
const exporting = pageNoLimit === true || String(pageNoLimit) === 'true'
if (exporting) { options.pageIndex = 0; options.pageSize = 1000; delete options.cursor }
let result = {hits:[],total:0,notices:[]}; queryError = ''
try { result = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters(options).call() }
catch (error) { queryError = String(error) }
const allHits = [...(result.hits || [])]
if (exporting) {
    let next = result.nextCursor
    while (next && (retrievalMode || 'lexical') === 'lexical' && allHits.length < result.total && allHits.length < 50000) {
        const page = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters(Object.assign({},options,{cursor:next})).call()
        if (!page.hits || !page.hits.length) break
        allHits.push(...page.hits); next = page.nextCursor
    }
    ec.logger.info('Report document export by '+String(ec.user.userId)+' for dataset '+datasetId+': '+allHits.length+' rows')
}
documentList = allHits.map(hit => Object.assign({},hit.body || {},{documentId:hit.id,documentType:hit.documentId,documentTitle:hit.documentTitle || '',authorizedLinks:hit.links || [],highlightsText:Object.values(hit.highlights || {}).flat().join(' · ')}))
if (order === 'oldest') documentList.reverse()
nextCursor = result.nextCursor
documentListCount = result.total || 0
documentListPageIndex = parseInt(pageIndex || '0', 10)
documentListPageSize = parseInt(pageSize || '50', 10)
documentListPageMaxIndex = Math.max(0,Math.ceil(documentListCount / documentListPageSize)-1)
documentListPageRangeLow = documentList.length ? documentListPageIndex*documentListPageSize+1 : 0
documentListPageRangeHigh = documentListPageIndex*documentListPageSize+documentList.length
queryNotices = (result.notices || []).map(notice=>typeof notice==='string'?notice:notice.message || JSON.stringify(notice))
fieldNames = Array.from(new Set(documentList.flatMap(doc => Object.keys(doc)))).filter(name => name !== 'attributes' && name !== 'events')
const stamp = value => { const date = new Date(/^\d+$/.test(String(value)) ? Number(value) : value); return Number.isNaN(date.getTime()) ? String(value || '') : date.toISOString() }
documentList = documentList.map(doc => Object.assign(doc,{documentJson:JSON.stringify(doc,null,2),
    timestampText:stamp(doc.timestamp || doc.start || doc.last_seen || doc.bucket_start || 0),
    summary:String(doc.body || doc.name || doc.message || doc.documentId || ''),
    shortSummary:String(doc.body || doc.name || doc.message || doc.documentId || '').slice(0,240),
    userId:doc['user.id'] || '',threadName:doc['thread.name'] || '',threadId:doc['thread.id'] || '',
    visitorId:doc['moqui.visitor.id'] || '',hostName:doc['host.name'] || doc['resource.host.name'] || doc['service.instance.id'] || '',
    logger:doc.scope_name || '',exceptionType:doc['exception.type'] || '',exceptionMessage:doc['exception.message'] || '',exceptionStack:doc['exception.stacktrace'] || '',
    anchorTime:doc[(result.dataset || {}).timeField || 'timestamp'] || ''}))
documentList=documentList.map(doc=>{
    const hostField=doc['host.name']?'host.name':doc['resource.host.name']?'resource.host.name':'service.instance.id'
    const threadField=doc['thread.name']?'thread.name':'thread.id'
    const summaryField=typeof doc.body==='string'?'body':typeof doc.name==='string'?'name':typeof doc.message==='string'?'message':'_id'
    const values={severity_text:doc.severity_text,thread:doc[threadField],host:doc[hostField],user:doc['user.id'],visitor:doc['moqui.visitor.id'],logger:doc.scope_name,summary:doc[summaryField] ?? doc.documentId}
    const names={severity_text:'severity_text',thread:threadField,host:hostField,user:'user.id',visitor:'moqui.visitor.id',logger:'scope_name',summary:summaryField}
    const cellFilters={}
    for(const [key,value] of Object.entries(values)){
        const field=names[key],allowed=!exporting && (field==='_id' || (datasetInfo.fields || []).some(meta=>meta.name===field && meta.searchable!==false)),query={field:{name:field,op:value==null?'exists':'eq',...(value==null?{}:{value})}}
        const pill={datasetId,query,label:field+': '+String(value ?? 'Missing'),negated:value==null,disabled:false,pinned:false}
        cellFilters[key]={field,value:value ?? null,allowed,forJson:allowed?JSON.stringify([...filterPills,pill]):null,outJson:allowed?JSON.stringify([...filterPills,Object.assign({},pill,{negated:!pill.negated})]):null}
    }
    return Object.assign(doc,{cellFilters})
})
autocompleteValues={}
for (const field of datasetFields) {
    if (field.type==='string' || field.type==='boolean' || field.type==='number') autocompleteValues[field.name]=Array.from(new Set(documentList.map(doc=>doc[field.name]).filter(value=>value!=null && typeof value!=='object' && String(value).length<=80))).slice(0,20)
}
histogramFrame = {fields:[]};topValues = []
if (!queryError) {
    const base = {datasetId,from,thru,queryString:queryString || '',filters:filterPills}
    try {
        const histogram = ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({query:Object.assign({},base,{
            aggregations:[{id:'time',type:'date_histogram',role:'x-axis',params:{field:datasetInfo.timeField,interval:'auto',targetBars:60}}]
        })}).call()
        histogramFrame = (histogram.frames || [])[0] || {fields:[]}
        if (fieldName) {
            const terms = ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({query:Object.assign({},base,{
                aggregations:[{id:'value',type:'terms',role:'x-axis',params:{field:fieldName,size:20}}]
            })}).call()
            const frame=(terms.frames || [])[0] || {fields:[]},values=frame.fields.find(field=>field.name==='value'),counts=frame.fields.find(field=>field.name==='count')
            if (values) topValues=values.values.map((value,index)=>({value,count:counts?counts.values[index]:null}))
        }
    } catch (error) { ec.logger.error('Explore field analysis failed: '+String(error));queryNotices.push(String(error)) }
}
